import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.BPFk9-tb.js";const u=JSON.parse('{"title":"ZeroNet常见问题","description":"","frontmatter":{"date":"2017-10-26T08:22:20","title":"ZeroNet常见问题","categories":["zeronet"],"tags":["ZeroNet"]},"headers":[{"level":2,"title":"我需要开放端口么？","slug":"我需要开放端口么","link":"#我需要开放端口么","children":[]},{"level":2,"title":"ZeroNet是匿名的么？","slug":"zeronet是匿名的么","link":"#zeronet是匿名的么","children":[]},{"level":2,"title":"在Tor浏览器中如何使用ZeroNet？","slug":"在tor浏览器中如何使用zeronet","link":"#在tor浏览器中如何使用zeronet","children":[]},{"level":2,"title":"在ZeroNet中如何使用Tor?","slug":"在zeronet中如何使用tor","link":"#在zeronet中如何使用tor","children":[]},{"level":2,"title":"能否使用一个配置文件？","slug":"能否使用一个配置文件","link":"#能否使用一个配置文件","children":[]},{"level":2,"title":"如果ISP和政府屏蔽了Tor如何使它工作？","slug":"如果isp和政府屏蔽了tor如何使它工作","link":"#如果isp和政府屏蔽了tor如何使它工作","children":[]},{"level":2,"title":"不同机器可以使用相同用户名么？","slug":"不同机器可以使用相同用户名么","link":"#不同机器可以使用相同用户名么","children":[]},{"level":2,"title":"如何创建一个“特殊”的网站地址？","slug":"如何创建一个-特殊-的网站地址","link":"#如何创建一个-特殊-的网站地址","children":[]},{"level":2,"title":"如何注册一个.bit的域名。","slug":"如何注册一个-bit的域名。","link":"#如何注册一个-bit的域名。","children":[]},{"level":2,"title":"我是否可以通过生成的网站地址/私钥来接收比特币支付？","slug":"我是否可以通过生成的网站地址-私钥来接收比特币支付","link":"#我是否可以通过生成的网站地址-私钥来接收比特币支付","children":[]},{"level":2,"title":"当有人托管恶意内容时会发生什么？","slug":"当有人托管恶意内容时会发生什么","link":"#当有人托管恶意内容时会发生什么","children":[]},{"level":2,"title":"能否通过远程的方式来安装ZeroNet？","slug":"能否通过远程的方式来安装zeronet","link":"#能否通过远程的方式来安装zeronet","children":[]},{"level":2,"title":"有什么方式可以跟踪ZeroNet使用的带宽？","slug":"有什么方式可以跟踪zeronet使用的带宽","link":"#有什么方式可以跟踪zeronet使用的带宽","children":[]},{"level":2,"title":"当两个人用相同的key来更新网站时会发生什么？","slug":"当两个人用相同的key来更新网站时会发生什么","link":"#当两个人用相同的key来更新网站时会发生什么","children":[]},{"level":2,"title":"ZeroNet是否使用了比特币的区块链？","slug":"zeronet是否使用了比特币的区块链","link":"#zeronet是否使用了比特币的区块链","children":[]},{"level":2,"title":"ZeroNet是否只支持HTML和CSS的网站？","slug":"zeronet是否只支持html和css的网站","link":"#zeronet是否只支持html和css的网站","children":[]},{"level":2,"title":"如何创建一个ZeroNet网站？","slug":"如何创建一个zeronet网站","link":"#如何创建一个zeronet网站","children":[]},{"level":2,"title":"运行的原理是什么？","slug":"运行的原理是什么","link":"#运行的原理是什么","children":[]}],"relativePath":"posts/zeronet/zeronet-1.md","filePath":"posts/zeronet/zeronet-1.md"}'),r={name:"posts/zeronet/zeronet-1.md"};function s(l,e,i,p,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h2 id="我需要开放端口么" tabindex="-1">我需要开放端口么？ <a class="header-anchor" href="#我需要开放端口么" aria-label="Permalink to &quot;我需要开放端口么？&quot;">​</a></h2><p>这个是可选的，如果你只是浏览和使用ZeroNet，你可以不需要开放端口。如果你要创建一个站点，强烈推荐你要开放一个端口。 ZeroNet在启动时会尝试用UPnP来打开一个端口，如果失败了，你需要手动开启：</p><ul><li>通过<code>http://192.168.1.1 </code>或者 <code>http://192.168.0.1</code>来访问你的路由器页面。</li><li>查找<code>开启UPnP支持</code>的类似选项，然后重启ZeroNet。 如果还是不起作用，查看<code>端口转发</code>章节。不同的路由器各有不同。转发端口是15441。</li></ul><h2 id="zeronet是匿名的么" tabindex="-1">ZeroNet是匿名的么？ <a class="header-anchor" href="#zeronet是匿名的么" aria-label="Permalink to &quot;ZeroNet是匿名的么？&quot;">​</a></h2><p>ZeroNet没有比BitTorrent提供更多的匿名性，但随着节点的增加，隐私（找到评论或站点所有者）会变得严峻。 ZeroNet在匿名网络中也做了一些工作：你可以使用Tor网络轻松的隐藏你的IP。</p><h2 id="在tor浏览器中如何使用zeronet" tabindex="-1">在Tor浏览器中如何使用ZeroNet？ <a class="header-anchor" href="#在tor浏览器中如何使用zeronet" aria-label="Permalink to &quot;在Tor浏览器中如何使用ZeroNet？&quot;">​</a></h2><p>推荐使用Tor浏览器来使用ZeroNet：</p><ul><li>启动Tor Browser</li><li>打开<code>abaut:perferences#advanced</code></li><li>点击<code>设置</code></li><li>在不需要代理的输入框中填入<code>127.0.0.1</code></li><li>在浏览器中打开<code>http://127.0.0.1:43110</code> 如果你看到的是空白页面，点击工具栏上的无脚本按钮，选择临时允许所有页面，重新加载页面。</li></ul><h2 id="在zeronet中如何使用tor" tabindex="-1">在ZeroNet中如何使用Tor? <a class="header-anchor" href="#在zeronet中如何使用tor" aria-label="Permalink to &quot;在ZeroNet中如何使用Tor?&quot;">​</a></h2><p>如果你希望隐藏你的IP，安装ZeroNet的最新版本然后点南Tor&gt;每个连接都启动Tor。</p><p>在Windows上Tor和ZeroNet是打包在一起的，ZeroNet在第一次运行的时启尝试下载和解压Tor。如果因为某些情况安装失败了，可以根据<code>core\\tools\\tor\\manual_install.txt</code>的说明来安装。</p><p>其他操作系统根据<a href="https://www.torproject.org/docs/installguide.html" target="_blank" rel="noreferrer">安装说明</a>进行安装，修改你的torrc的配置文件，把<code># ControlPort 9051</code>的<code>#</code>去掉，然后重启你的Tor服务和ZeroNet。</p><blockquote><p>提示：你可以通过ZeroNet的<a href="http://127.0.0.1:43110/Stats" target="_blank" rel="noreferrer">状态页</a>来验证你的IP。 提示：如果你连接时发生错误，请检查你是否安装了最新版本的Tor（需要0.2.7.5以上版本）</p></blockquote><h1 id="linux系统中zeronet如何使用tor" tabindex="-1">Linux系统中ZeroNet如何使用Tor？ <a class="header-anchor" href="#linux系统中zeronet如何使用tor" aria-label="Permalink to &quot;Linux系统中ZeroNet如何使用Tor？&quot;">​</a></h1><p>更新最新版本的Tor（我们需要0.2.7.5+版本），执行这些<a href="https://www.torproject.org/docs/debian.html.en" target="_blank" rel="noreferrer">操作</a>。以Debian为例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &#39;deb http://deb.torproject.org/torproject.org jessie main&#39;&gt;&gt; /etc/apt/sources.list.d/tor.list</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gpg --keyserver keys.gnupg.net --recv 886DDD89</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gpg --export A3C4F0F979CAA22CDBA8F512EE8CBC9E886DDD89 | apt-key add -</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt-get update</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt-get install tor</span></span></code></pre></div><p>修改配置文件开启控制协议：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcedit /etc/tor/torrc</span></span></code></pre></div><p>删除<code>ControlPort 9051</code>和<code>CookieAuthentication 1</code>(大概在57行)的<code>#</code>字符。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/etc/init.d/tor restart</span></span></code></pre></div><p>通过<code>usermod -a -G debian-tor [yourlinuxuser]</code>来授权访问cookie。（如果不是使用Debian通过<code>ls -al /var/run/tor/control.authcookie</code>的查看文件的用户组）。 注销/登录来使修改生效。</p><blockquote><p>提示：可以通过<code>echo &#39;PROTOCALINFO&#39; | nc 127.0.0.1 9051</code>来验证Tor是否正常运行。 提示：你可以不修改Tor的配置，仅通过<code>zeronet.py --tor disabe --proxy 127.0.0.1:9050 --disable_udp</code>来使用Tor，但这样你会失去与其他.onion地址通话的能力。</p></blockquote><h2 id="能否使用一个配置文件" tabindex="-1">能否使用一个配置文件？ <a class="header-anchor" href="#能否使用一个配置文件" aria-label="Permalink to &quot;能否使用一个配置文件？&quot;">​</a></h2><p>你可以把选项配置在<code>zeronet.conf</code>文件中。比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[global]</span></span>
<span class="line"><span>data_dir = my-data-dir</span></span>
<span class="line"><span>log_dir = my-log-dir</span></span>
<span class="line"><span>ui_restrict =</span></span>
<span class="line"><span> 1.2.3.4</span></span>
<span class="line"><span> 2.3.4.5</span></span></code></pre></div><p>使用<code>zeronet.py --help</code>命令查看所有的选项。</p><h2 id="如果isp和政府屏蔽了tor如何使它工作" tabindex="-1">如果ISP和政府屏蔽了Tor如何使它工作？ <a class="header-anchor" href="#如果isp和政府屏蔽了tor如何使它工作" aria-label="Permalink to &quot;如果ISP和政府屏蔽了Tor如何使它工作？&quot;">​</a></h2><p>ZeroNet暂时未包含<a href="https://www.torproject.org/docs/pluggable-transports.html.en" target="_blank" rel="noreferrer">Tor pluggable transports</a>。访问Tor网络的最简单的方法就是使用Tor浏览器。修改它的配置开启可拨插传输，然后修改ZeroNet的配置，使用Tor浏览器代理和控制端口。 通过<code>--tor_controller 127.0.0.1:9151 --tor-proxy 127.0.0.1:9150</code>来启动ZeroNet或者在<code>zeronet.conf</code>中添加如下参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[global]</span></span>
<span class="line"><span>tor_controller = 127.0.0.1:9151</span></span>
<span class="line"><span>tor_proxy = 127.0.0.1:9150</span></span></code></pre></div><h2 id="不同机器可以使用相同用户名么" tabindex="-1">不同机器可以使用相同用户名么？ <a class="header-anchor" href="#不同机器可以使用相同用户名么" aria-label="Permalink to &quot;不同机器可以使用相同用户名么？&quot;">​</a></h2><p>可以，只要你把<code>data/user.json</code>文件拷贝到时你的新机器就可以了。</p><h2 id="如何创建一个-特殊-的网站地址" tabindex="-1">如何创建一个“特殊”的网站地址？ <a class="header-anchor" href="#如何创建一个-特殊-的网站地址" aria-label="Permalink to &quot;如何创建一个“特殊”的网站地址？&quot;">​</a></h2><p>通过<a href="https://bitcointalk.org/index.php?topic=25804.0" target="_blank" rel="noreferrer">vanitygen</a>来生成。一旦你生成了你的key,创建<code>data/你的key</code>目录。在这个目录下放一些文件。 然后访问<code>http://127.0.0.1:43110/你的key/</code>.将<code>0</code>按钮拖到左边，然后用侧边栏来注册你的网站。</p><h2 id="如何注册一个-bit的域名。" tabindex="-1">如何注册一个.bit的域名。 <a class="header-anchor" href="#如何注册一个-bit的域名。" aria-label="Permalink to &quot;如何注册一个.bit的域名。&quot;">​</a></h2><p>你可以通过<a href="https://namecoin.info/" target="_blank" rel="noreferrer">Namacoin</a>来注册一个.bit域名。通过GUI客户端或者<a href="http://www.christopherpoole.net/registering-a-bit-domain-with-namecoin.html" target="_blank" rel="noreferrer">命令行接口</a>来管理你的域名。 一旦你注册完成，你需需增加一个<code>zeronet</code>节点来记录它。比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>    &quot;zeronet&quot;: {</span></span>
<span class="line"><span>        &quot;&quot;: &quot;1EU1tbG9oC1A8jz2ouVwGZyQ5asrNsE4Vr&quot;,</span></span>
<span class="line"><span>        &quot;blog&quot;: &quot;1BLogC9LN4oPDcruNz3qo1ysa133E9AGg8&quot;,</span></span>
<span class="line"><span>        &quot;talk&quot;: &quot;1TaLk3zM7ZRskJvrh3ZNCDVGXvkJusPKQ&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>&quot;&quot;是顶级域名，其他的是子域名。</p><blockquote><p>提示:你可以通过<a href="https://shapeshift.io/" target="_blank" rel="noreferrer">shapeshift.io</a>来购买比特币或者其他加密货币的Namecoin。 提示:一些可以注册.bit域名的站点：<a href="https://domaincoin.net/" target="_blank" rel="noreferrer">domaincoin.net</a>, <a href="https://peername.com/" target="_blank" rel="noreferrer">peername.com</a>, <a href="https://dotbit.me/" target="_blank" rel="noreferrer">dotbit.me</a> 提示：你可以在<a href="http://namecha.in/" target="_blank" rel="noreferrer">namecha.in</a>中验证你的域名。比如:<code>zeorid.bit</code> 提示：在域名中只能使用小写字母，数字和-。 提示：要让ZeroHello显示你的域名而不是比特币网址，你需要在<code>content.json</code>中增加<code>domain</code>键.比如：</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>&quot;address&quot;: &quot;1BLogC9LN4oPDcruNz3qo1ysa133E9AGg8&quot;,</span></span>
<span class="line"><span> &quot;background-color&quot;: &quot;white&quot;,</span></span>
<span class="line"><span> &quot;cloneable&quot;: true,</span></span>
<span class="line"><span> &quot;description&quot;: &quot;Blogging platform Demo&quot;,</span></span>
<span class="line"><span> &quot;domain&quot;: &quot;Blog.ZeroNetwork.bit&quot;,</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="我是否可以通过生成的网站地址-私钥来接收比特币支付" tabindex="-1">我是否可以通过生成的网站地址/私钥来接收比特币支付？ <a class="header-anchor" href="#我是否可以通过生成的网站地址-私钥来接收比特币支付" aria-label="Permalink to &quot;我是否可以通过生成的网站地址/私钥来接收比特币支付？&quot;">​</a></h2><p>是的，这个地址是一个标准的比特币地址。私钥也是WIF格式的，因此你可以把它导到大部分的客户端里。</p><blockquote><p>提示：建议不要在你的网站地址中放太多钱，因为每次更新你的网站的时候就需要使用你的私钥。</p></blockquote><h2 id="当有人托管恶意内容时会发生什么" tabindex="-1">当有人托管恶意内容时会发生什么？ <a class="header-anchor" href="#当有人托管恶意内容时会发生什么" aria-label="Permalink to &quot;当有人托管恶意内容时会发生什么？&quot;">​</a></h2><p>Zeronet的网站是沙箱化的，他们的拥有权限和你在互联网上访问的其他站点一样。你可以完全控制托管理的内容。如果你发现可疑内容，你随时都可以停止托管。</p><h2 id="能否通过远程的方式来安装zeronet" tabindex="-1">能否通过远程的方式来安装ZeroNet？ <a class="header-anchor" href="#能否通过远程的方式来安装zeronet" aria-label="Permalink to &quot;能否通过远程的方式来安装ZeroNet？&quot;">​</a></h2><h2 id="有什么方式可以跟踪zeronet使用的带宽" tabindex="-1">有什么方式可以跟踪ZeroNet使用的带宽？ <a class="header-anchor" href="#有什么方式可以跟踪zeronet使用的带宽" aria-label="Permalink to &quot;有什么方式可以跟踪ZeroNet使用的带宽？&quot;">​</a></h2><p>ZeroNet的侧边栏会展示发送和接收的字节（将<code>0</code>按钮拖到左边打开侧边栏）。</p><blockquote><p>提示：所有连接的统计<code>http://127.0.0.1:43110/Stats</code></p></blockquote><h2 id="当两个人用相同的key来更新网站时会发生什么" tabindex="-1">当两个人用相同的key来更新网站时会发生什么？ <a class="header-anchor" href="#当两个人用相同的key来更新网站时会发生什么" aria-label="Permalink to &quot;当两个人用相同的key来更新网站时会发生什么？&quot;">​</a></h2><p>每个content.json是有时间戳的，所有的客户端只接收最新的那个。</p><h2 id="zeronet是否使用了比特币的区块链" tabindex="-1">ZeroNet是否使用了比特币的区块链？ <a class="header-anchor" href="#zeronet是否使用了比特币的区块链" aria-label="Permalink to &quot;ZeroNet是否使用了比特币的区块链？&quot;">​</a></h2><p>没有，Zeronet只是使用了比特币的加密算法用于网站地址和内容签名和验证。用户的标识是基于比特币的<a href="https://github.com/bitcoin/bips/blob/master/bip-0032.mediawiki" target="_blank" rel="noreferrer">BIP32</a>格式</p><p>Namecoin的区块链用于域名注册。</p><h2 id="zeronet是否只支持html和css的网站" tabindex="-1">ZeroNet是否只支持HTML和CSS的网站？ <a class="header-anchor" href="#zeronet是否只支持html和css的网站" aria-label="Permalink to &quot;ZeroNet是否只支持HTML和CSS的网站？&quot;">​</a></h2><p>ZeroNet is built for dynamic, real-time updated websites, but you can serve any kind of files using it. (VCS repositories, your own thin-client, database, etc.)</p><p>ZeroNet用于构建动态和实时更新的站，或者任何的文件类型（VCS仓库，瘦客户端，数据库等等）</p><h2 id="如何创建一个zeronet网站" tabindex="-1">如何创建一个ZeroNet网站？ <a class="header-anchor" href="#如何创建一个zeronet网站" aria-label="Permalink to &quot;如何创建一个ZeroNet网站？&quot;">​</a></h2><p>按<a href="http://zeronet.readthedocs.io/en/latest/using_zeronet/create_new_site/" target="_blank" rel="noreferrer">操作说明</a></p><h2 id="运行的原理是什么" tabindex="-1">运行的原理是什么？ <a class="header-anchor" href="#运行的原理是什么" aria-label="Permalink to &quot;运行的原理是什么？&quot;">​</a></h2><ul><li>当你打开一个新的站点，需要访问者在BitTorrent网络的IP地址。</li><li>首先下载content.json文件，这个文件包含了所有的文件名，散列和网站所有者的加密签名。</li><li>通过网站地址和文件中的网站所有者的签名来验证下载的content.json文件。</li><li>下载其他文件（html，css，js……）并通过content.json中的SHA512散列值进行验证。</li><li>你会托管所有你访问过的网站。</li><li>如果网站的所有者（拥有网站私钥的人）修改了网站，然后他签名一个新的content.json并发布到各个节点。当节点验证了content.json的真实性（通过签名），下载修改的文件并发布给其他节点。 更多信息：<a href="http://zeronet.readthedocs.io/en/latest/using_zeronet/sample_sites/" target="_blank" rel="noreferrer">ZeroNet简单网站介绍</a>，<a href="https://docs.google.com/presentation/d/1_2qK1IuOKJ51pgBvllZ9Yu7Au2l551t3XBgyTSvilew/pub" target="_blank" rel="noreferrer">ZeroNet工作原理幻灯片</a></li></ul>`,64)])])}const b=t(r,[["render",s]]);export{u as __pageData,b as default};
